from collections import deque
def clone_graph(node):
    if not node: return None
    seen = {node: Node(node.val)}
    q = deque([node])
    while q:
        n = q.popleft()
        for nb in n.neighbors:
            if nb not in seen:
                seen[nb] = Node(nb.val); q.append(nb)
            seen[n].neighbors.append(seen[nb])
    return seen[node]

def calc_equation(equations, values, queries):
    adj = {}
    for (a, b), v in zip(equations, values):
        adj.setdefault(a, []).append((b, v))
        adj.setdefault(b, []).append((a, 1/v))
    def dfs(a, b, prod, seen):
        if a not in adj: return -1
        if a == b: return prod
        seen.add(a)
        for nb, w in adj[a]:
            if nb not in seen:
                r = dfs(nb, b, prod*w, seen)
                if r != -1: return r
        return -1
    res = []
    for a, b in queries:
        res.append(dfs(a, b, 1.0, set()) if a == b else dfs(a, b, 1.0, set()))
    return res

def calc_equation(equations, values, queries):
    g = {}
    for (a, b), v in zip(equations, values):
        g.setdefault(a, {})[b] = v
        g.setdefault(b, {})[a] = 1/v
    nodes = list(g)
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if i in g and k in g[i] and j in g[k]:
                    g.setdefault(i, {})[j] = g[i][k] * g[k][j]
    return [g.get(a, {}).get(b, -1.0) for a, b in queries]

