def snakes_and_ladders(board):
    n = len(board)
    def idx(s):
        r, c = divmod(s-1, n)
        if r % 2: c = n-1-c
        return n-1-r, c
    q = deque([(1, 0)]); seen = {1}
    while q:
        s, d = q.popleft()
        if s == n*n: return d
        for k in range(1, 7):
            nxt = s + k
            if nxt > n*n: continue
            r, c = idx(nxt)
            if board[r][c] != -1: nxt = board[r][c]
            if nxt not in seen:
                seen.add(nxt); q.append((nxt, d+1))
    return -1

